package com.c203.limit.domain.admin.service;
import java.time.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.c203.limit.domain.admin.entity.AdminActionLog;import com.c203.limit.domain.admin.repository.*;import com.c203.limit.domain.inquiry.entity.Inquiry;import com.c203.limit.domain.inquiry.repository.InquiryRepository;import com.c203.limit.domain.member.entity.*;import com.c203.limit.domain.member.repository.MemberRepository;import com.c203.limit.domain.seller.entity.*;import com.c203.limit.domain.seller.repository.*;import com.c203.limit.domain.withdrawal.entity.WithdrawalRequest;import com.c203.limit.domain.withdrawal.repository.WithdrawalRequestRepository;import com.c203.limit.global.response.PageResponse;
@Service public class AdminSearchService{
 private final MemberRepository members;private final MemberRestrictionRepository restrictions;private final SellerApplicationRepository applications;private final SellerRepository sellers;private final InquiryRepository inquiries;private final WithdrawalRequestRepository withdrawals;private final AdminActionLogRepository logs;
 public AdminSearchService(MemberRepository m,MemberRestrictionRepository r,SellerApplicationRepository a,SellerRepository s,InquiryRepository i,WithdrawalRequestRepository w,AdminActionLogRepository l){members=m;restrictions=r;applications=a;sellers=s;inquiries=i;withdrawals=w;logs=l;}
 @Transactional(readOnly=true)public PageResponse<Map<String,Object>> members(Integer p,Integer s,String email,String nickname,String status,String role,LocalDate from,LocalDate to){Specification<Member> spec=(root,q,cb)->cb.conjunction();if(text(email))spec=spec.and((r,q,cb)->cb.like(cb.lower(r.get("email")),"%"+email.toLowerCase()+"%"));if(text(nickname))spec=spec.and((r,q,cb)->cb.like(cb.lower(r.get("nickname")),"%"+nickname.toLowerCase()+"%"));if(text(status))spec=spec.and((r,q,cb)->cb.equal(r.get("status"),MemberStatus.valueOf(status)));if(text(role))spec=spec.and((r,q,cb)->cb.equal(r.get("role"),MemberRole.valueOf(role)));if(from!=null)spec=spec.and((r,q,cb)->cb.greaterThanOrEqualTo(r.get("createdAt"),from.atStartOfDay().atOffset(ZoneOffset.UTC)));if(to!=null)spec=spec.and((r,q,cb)->cb.lessThan(r.get("createdAt"),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC)));var result=members.findAll(spec,pageable(p,s,"createdAt"));return page(result,result.stream().map(m->map("memberId",m.getId(),"email",mask(m.getEmail()),"nickname",m.getNickname(),"status",m.getStatus().name(),"roles",Set.of(m.getRole().name()),"activeRestrictionCount",restrictions.countByMemberIdAndStatus(m.getId(),"ACTIVE"),"createdAt",m.getCreatedAt())).toList());}
 @Transactional(readOnly=true)public PageResponse<Map<String,Object>> applications(Integer p,Integer s,String status,String type,String country,String from,String to){Specification<SellerApplication> spec=(r,q,cb)->cb.conjunction();if(text(status))spec=spec.and((r,q,cb)->cb.equal(r.get("status"),SellerApplicationStatus.valueOf(status)));if(text(type))spec=spec.and((r,q,cb)->cb.equal(r.get("type"),SellerType.valueOf(type)));if(text(country))spec=spec.and((r,q,cb)->cb.equal(r.get("countryCode"),country));if(text(from)){var time=OffsetDateTime.parse(from);spec=spec.and((r,q,cb)->cb.greaterThanOrEqualTo(r.get("submittedAt"),time));}if(text(to)){var time=OffsetDateTime.parse(to);spec=spec.and((r,q,cb)->cb.lessThanOrEqualTo(r.get("submittedAt"),time));}var result=applications.findAll(spec,pageable(p,s,"createdAt"));return page(result,result.stream().map(a->map("applicationId",a.getId(),"memberId",a.getMember().getId(),"applicantEmail",mask(a.getApplicantEmail()),"sellerType",a.getType().name(),"countryCode",a.getCountryCode(),"status",a.getStatus().name(),"applicationVersion",a.getVersion(),"submittedAt",a.getSubmittedAt())).toList());}
 @Transactional(readOnly=true)public PageResponse<Map<String,Object>> sellers(Integer p,Integer size,String status,String type,String country,String keyword){Specification<Seller> spec=(r,q,cb)->cb.conjunction();if(text(status))spec=spec.and((r,q,cb)->cb.equal(r.get("status"),status));if(text(type))spec=spec.and((r,q,cb)->cb.equal(r.get("type"),SellerType.valueOf(type)));if(text(country))spec=spec.and((r,q,cb)->cb.equal(r.get("countryCode"),country));if(text(keyword))spec=spec.and((r,q,cb)->cb.or(cb.like(cb.lower(r.get("businessName")),"%"+keyword.toLowerCase()+"%"),cb.like(cb.lower(r.get("member").get("email")),"%"+keyword.toLowerCase()+"%")));var result=sellers.findAll(spec,pageable(p,size,"approvedAt"));return page(result,result.stream().map(x->map("sellerProfileId",x.getId(),"memberId",x.getMember().getId(),"memberEmail",mask(x.getMember().getEmail()),"businessName",x.getBusinessName(),"sellerType",x.getType().name(),"sellerStatus",x.getStatus(),"countryCode",x.getCountryCode(),"productLimit",x.getProductLimit(),"salesAmountLimit",x.getSalesAmountLimit(),"approvedAt",x.getApprovedAt())).toList());}
 @Transactional(readOnly=true)public PageResponse<Map<String,Object>> inquiries(Integer p,Integer size,String status,String category,Long memberId,LocalDate from,LocalDate to){Specification<Inquiry> spec=(r,q,cb)->cb.conjunction();if(text(status))spec=spec.and((r,q,cb)->cb.equal(r.get("status"),status));if(text(category))spec=spec.and((r,q,cb)->cb.equal(r.get("category"),category));if(memberId!=null)spec=spec.and((r,q,cb)->cb.equal(r.get("member").get("id"),memberId));spec=date(spec,"createdAt",from,to);var result=inquiries.findAll(spec,pageable(p,size,"createdAt"));return page(result,result.stream().map(x->map("inquiryId",x.getId(),"memberId",x.getMember().getId(),"memberEmail",mask(x.getMember().getEmail()),"category",x.getCategory(),"title",x.getTitle(),"status",x.getStatus(),"createdAt",x.getCreatedAt())).toList());}
 @Transactional(readOnly=true)public PageResponse<Map<String,Object>> withdrawals(Integer p,Integer size,String status,String from,String to){Specification<WithdrawalRequest> spec=(r,q,cb)->cb.conjunction();if(text(status))spec=spec.and((r,q,cb)->cb.equal(r.get("status"),status));if(text(from)){var t=OffsetDateTime.parse(from);spec=spec.and((r,q,cb)->cb.greaterThanOrEqualTo(r.get("requestedAt"),t));}if(text(to)){var t=OffsetDateTime.parse(to);spec=spec.and((r,q,cb)->cb.lessThanOrEqualTo(r.get("requestedAt"),t));}var result=withdrawals.findAll(spec,pageable(p,size,"requestedAt"));return page(result,result.stream().map(x->map("withdrawalRequestId",x.getId(),"memberId",x.getMember().getId(),"memberEmail",mask(x.getMember().getEmail()),"status",x.getStatus(),"requestedAt",x.getRequestedAt())).toList());}
 @Transactional(readOnly=true)public PageResponse<Map<String,Object>> logs(Integer p,Integer size,Long admin,String action,String target,Long targetId,LocalDate from,LocalDate to){Specification<AdminActionLog> spec=(r,q,cb)->cb.conjunction();if(admin!=null)spec=spec.and((r,q,cb)->cb.equal(r.get("adminId"),admin));if(text(action))spec=spec.and((r,q,cb)->cb.equal(r.get("actionType"),action));if(text(target))spec=spec.and((r,q,cb)->cb.equal(r.get("targetType"),target));if(targetId!=null)spec=spec.and((r,q,cb)->cb.equal(r.get("targetId"),targetId));spec=date(spec,"createdAt",from,to);var result=logs.findAll(spec,pageable(p,size,"createdAt"));return page(result,result.stream().map(x->map("adminActionLogId",x.getId(),"adminId",x.getAdminId(),"actionType",x.getActionType(),"targetType",x.getTargetType(),"targetId",x.getTargetId(),"reason",x.getReason(),"createdAt",x.getCreatedAt())).toList());}
 private <T>Specification<T> date(Specification<T>s,String field,LocalDate from,LocalDate to){if(from!=null)s=s.and((r,q,cb)->cb.greaterThanOrEqualTo(r.get(field),from.atStartOfDay().atOffset(ZoneOffset.UTC)));if(to!=null)s=s.and((r,q,cb)->cb.lessThan(r.get(field),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC)));return s;}private Pageable pageable(Integer p,Integer s,String sort){return PageRequest.of(p==null?0:Math.max(0,p),s==null?20:Math.min(100,Math.max(1,s)),Sort.by(Sort.Direction.DESC,sort));}private <T>PageResponse<T>page(Page<?>p,List<T>c){return new PageResponse<>(c,p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages(),p.hasNext());}private boolean text(String v){return v!=null&&!v.isBlank();}private String mask(String e){if(e==null)return null;int at=e.indexOf('@');return at<1?"***":e.substring(0,1)+"***"+e.substring(at);}private Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}
}
